// Generated by Automated Quality Gate; review before merging.
const {
  add,
  subtract,
  multiply,
  divide,
  calculatePercentage,
  modulo,
  absoluteDifference
} = require('../../src/math');

describe('Math Utility Functions', () => {
  
  describe('add', () => {
    test('should add two positive numbers correctly', () => {
      expect(add(2, 3)).toBe(5);
    });

    test('should throw TypeError for non-number inputs', () => {
      expect(() => add(2, '3')).toThrow(TypeError);
    });
  });

  describe('subtract', () => {
    test('should subtract two numbers correctly', () => {
      expect(subtract(5, 3)).toBe(2);
    });

    test('should normalize -0 to 0', () => {
      expect(subtract(0, 0)).toBe(0);
      expect(Object.is(subtract(0, 0), -0)).toBe(false);
    });
  });

  describe('multiply', () => {
    test('should multiply two numbers correctly', () => {
      expect(multiply(4, 5)).toBe(20);
    });

    test('should throw TypeError for NaN input', () => {
      expect(() => multiply(2, NaN)).toThrow('Inputs must be valid numbers');
    });
  });

  describe('divide', () => {
    test('should divide two numbers correctly', () => {
      expect(divide(10, 2)).toBe(5);
    });

    test('should throw Error when dividing by zero', () => {
      expect(() => divide(10, 0)).toThrow('Cannot divide by zero');
    });

    test('should throw TypeError for infinite inputs', () => {
      expect(() => divide(10, Infinity)).toThrow('Inputs must be finite numbers');
    });
  });

  describe('calculatePercentage', () => {
    test('should return correct percentage', () => {
      expect(calculatePercentage(50, 200)).toBe(25);
    });

    test('should return 0 when total is 0', () => {
      expect(calculatePercentage(50, 0)).toBe(0);
    });
  });

  describe('modulo', () => {
    test('should return correct modulo', () => {
      expect(modulo(10, 3)).toBe(1);
    });

    test('should handle negative numbers correctly using mathematical modulo', () => {
      expect(modulo(-10, 3)).toBe(2);
    });

    test('should throw Error for modulo by zero', () => {
      expect(() => modulo(10, 0)).toThrow('Cannot modulo by zero');
    });
  });

  describe('absoluteDifference', () => {
    test('should return the absolute difference between two numbers', () => {
      expect(absoluteDifference(10, 20)).toBe(10);
      expect(absoluteDifference(20, 10)).toBe(10);
    });

    test('should throw TypeError for non-finite numbers', () => {
      expect(() => absoluteDifference(10, -Infinity)).toThrow('Inputs must be finite numbers');
    });
  });
});
